BEGIN;
ALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS jurisdiction_id TEXT;
ALTER TABLE users ALTER COLUMN password TYPE TEXT;
CREATE TABLE IF NOT EXISTS governed_poll_workers(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,worker_reference TEXT NOT NULL,eligibility_basis TEXT NOT NULL,training_modules JSONB NOT NULL DEFAULT '[]',languages JSONB NOT NULL DEFAULT '[]',accessibility_needs JSONB NOT NULL DEFAULT '[]',conflicts JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'eligible',created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(jurisdiction_id,idempotency_key));
CREATE TABLE IF NOT EXISTS poll_assignments(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,worker_id BIGINT NOT NULL REFERENCES governed_poll_workers(id),site_id TEXT NOT NULL,role TEXT NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,required_language TEXT,status TEXT NOT NULL DEFAULT 'assigned',assigned_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(starts_at<ends_at),UNIQUE(jurisdiction_id,idempotency_key));
CREATE TABLE IF NOT EXISTS poll_checkin_events(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,device_id TEXT NOT NULL,local_sequence BIGINT NOT NULL,worker_id BIGINT NOT NULL REFERENCES governed_poll_workers(id),site_id TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN('check_in','check_out','break_start','break_end')),recorded_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),received_by TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending_verification','verified','rejected')),UNIQUE(jurisdiction_id,device_id,local_sequence));
CREATE TABLE IF NOT EXISTS poll_ops_incidents(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,site_id TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('low','moderate','high','critical')),observed_facts TEXT NOT NULL,reported_by TEXT NOT NULL,dispatch_status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(jurisdiction_id,idempotency_key));
CREATE TABLE IF NOT EXISTS poll_dispatch_outbox(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,incident_id BIGINT NOT NULL UNIQUE REFERENCES poll_ops_incidents(id),payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending_manual_dispatch',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS poll_ops_events(id BIGSERIAL PRIMARY KEY,jurisdiction_id TEXT NOT NULL,actor_id TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,event_type TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS poll_assignment_worker_time_idx ON poll_assignments(jurisdiction_id,worker_id,starts_at,ends_at);
COMMIT;
